/* ── helpers ─────────────────────────────────────────────── */
const n   = v => v.toLocaleString('en-IN');
const esc = t => String(t).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
const cv  = (t, s) => `var(--vw-color-${t}-${s})`;
/* RAN/Core/Transport/IP-MPLS — same keys, same hex ramp as the React
   Insights/Reconciliation screens' DOMAIN_HEX/DOMAIN_LABEL (src/data/
   discoveryOverview.ts), so a domain reads the same colour everywhere,
   legacy screens included. */
/* The domain model is a tree, the same one src/data/discoveryOverview.ts
   declares (DOMAIN_PARENT): IP/MPLS is a packet-transport technology UNDER
   Transport, not a fourth sibling —
     RAN · Core · Transport └ IP/MPLS
   `parent` carries that here; domainDot() renders the parent muted in front
   of a sub-domain ("Transport · IP/MPLS"), DOMAIN_FILTER_OPTIONS lists the
   tree indented in every Domain filter, and domainFilterMatch() makes a
   Transport filter keep IP/MPLS rows. */
const DOMAIN_META = {
  RAN:       { n: 'RAN',      hex: cv('blue', 400) },
  Core:      { n: 'Core',     hex: cv('violet', 400) },
  Transport: { n: 'Transport',hex: cv('teal', 400) },
  IPMPLS:    { n: 'IP/MPLS',  hex: cv('pink', 400), parent: 'Transport' }
};
/* display order: each sub-domain directly after its parent */
const DOMAIN_ORDER = ['RAN', 'Core', 'Transport', 'IPMPLS'];
/* filter-panel options — {v, l} when the visible text is indented under a
   parent; the value stays the plain name a filter compares against */
const DOMAIN_FILTER_OPTIONS = DOMAIN_ORDER.map(k => DOMAIN_META[k].parent
  ? { v: DOMAIN_META[k].n, l: `   └ ${DOMAIN_META[k].n}` }
  : DOMAIN_META[k].n);
/* does a row tagged `key` fall under the Domain filter value `name`
   (case-insensitive short name)? Equal, or `name` is its parent. */
const domainFilterMatch = (key, name) => {
  const m = DOMAIN_META[key];
  if (!m) return false;
  const want = String(name).trim().toLowerCase();
  return m.n.toLowerCase() === want || (!!m.parent && DOMAIN_META[m.parent].n.toLowerCase() === want);
};
const domainDot = d => {
  const m = DOMAIN_META[d];
  const parent = m && m.parent ? `<span style="color:${cv('slate',500)};font-weight:400">${DOMAIN_META[m.parent].n} · </span>` : '';
  return `<span class="row" style="align-items:center;gap:8px;flex-wrap:nowrap"><span style="width:8px;height:8px;border-radius:50%;background:${m?.hex || cv('gray',400)};flex-shrink:0"></span><span>${parent}${m?.n || d}</span></span>`;
};
const pad2 = v => String(v).padStart(2, '0');
const MONTHS_SHORT = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
function getLiveDateSync(h = 9, m = 10) {
  const d = new Date();
  const day = pad2(d.getDate());
  return `${day}-${MONTHS_SHORT[d.getMonth()]}-${d.getFullYear()} ${pad2(h)}:${pad2(m)}`;
}
/* a point in real time, `hoursAgo` hours before this instant — proper date
   arithmetic (crosses midnight, month-end) rather than stamping today's date
   onto a fixed hour, so "N hours ago" is still true whenever this loads */
function relativeTimestamp(hoursAgo) {
  const d = new Date(Date.now() - hoursAgo * 3600 * 1000);
  return `${pad2(d.getDate())}-${MONTHS_SHORT[d.getMonth()]}-${d.getFullYear()} ${pad2(d.getHours())}:${pad2(d.getMinutes())}`;
}
/* same idea as relativeTimestamp, minute precision and no IST suffix — for
   the "last sync"/"last auth"/alarm-timestamp style fields, so a page never
   shows a fixed date that quietly falls further out of date every day */
function agoStamp(minsAgo, withSeconds) {
  const d = new Date(Date.now() - minsAgo * 60000);
  const time = `${pad2(d.getHours())}:${pad2(d.getMinutes())}${withSeconds ? ':' + pad2(d.getSeconds()) : ''}`;
  return `${pad2(d.getDate())}-${MONTHS_SHORT[d.getMonth()]}-${d.getFullYear()} ${time}`;
}
/* title="" gives every chip a native tooltip fallback of its own label —
   needed now that grid chips are sized to a per-column tier (see the
   .tbl-wrap chip-width rules in shell.css) rather than their own text, so a
   label longer than its tier's longest expected value ellipsis-truncates
   instead of stretching the box; the full text stays reachable on hover.
   esc() here (unlike the plain ${t} in the chip's own text below) matters
   because this one lands inside an HTML attribute, where a stray quote in
   the label would otherwise break out of it. */
const chip = (t, v, strong) => `<span class="vw-chip vw-chip--${v}${strong?' is-strong':''}" title="${esc(t)}">${t}</span>`;
const card = (inner, cls = '', style = '') =>
  `<section class="vw-card-section ${cls}"${style?` style="${style}"`:''}>${inner}</section>`;
const head = (t, d) =>
  `<div class="stack-x"><div class="vw-card-title">${t}</div>${d?`<div class="vw-card-description">${d}</div>`:''}</div>`;
const headSm = (t, d) =>
  `<div class="stack-x"><div class="vw-card-title-sm">${t}</div>${d?`<div class="vw-card-description">${d}</div>`:''}</div>`;
/* Screens named by the breadcrumb carry no title block; anything that used to
   sit beside the title becomes a control row, or moves into the grid's own menu. */
const pageBar = (controls) => `<div class="page-bar">${controls}</div>`;
const pageHead = (t, d, right = '') =>
  `<div class="page-head"><div class="stack-x" style="max-width:70ch">
     <h1 class="vw-page-title" style="margin:0">${t}</h1>
     <p class="vw-page-description" style="margin:0">${d}</p></div><div class="row">${right}</div></div>`;

/* A first column called Status or State gets the platform's full-width state
   pill rather than a chip that hugs its text — unless that column is marked
   { t:'Status', plain:true }, for a table that sits its own status chip next
   to same-sized ones elsewhere in the row (e.g. per-endpoint admin/
   operational status) and needs all of them to read as one consistent size. */
const STATUS_COL = /^(status|state|outcome|result|stock state)$/i;

/* acts: a function (rowIndex) => [A(...)], or an array of arrays, or null for no kebab.
   rowAttr: a function (rowIndex) => {attr: value} of extra <tr> attributes, or the row's
   own _attr, or null.
   rowDrill: a function (rowIndex) => {v,l,q} to make the whole row clickable to that drill
   target (or an array of the same) — wins over the auto-detected first kebab action below;
   leave null to fall back to that auto-detection, or to leave the row inert. */
const table = (cols, rows, cls = '', acts = null, rowAttr = null, rowDrill = null) => {
  const gid = 'g' + (GRID_N++);
  const menu = acts ? (typeof acts === 'function' ? acts : i => acts[i]) : null;
  const rowD = rowDrill ? (typeof rowDrill === 'function' ? rowDrill : i => rowDrill[i]) : null;
  const span = cols.length + (menu ? 1 : 0);
  return `<div class="tbl-wrap"><table class="nst-table ${cls}">
    <thead><tr>${cols.map(c=>`<th${c.r?' class="t-right"':''}>${c.t}</th>`).join('')}${menu?'<th class="kb-th"></th>':''}</tr></thead>
    <tbody>${rows.length
      ? rows.map((r,ri)=>{
          const items = menu ? (menu(ri) || []) : [];
          /* an explicit rowDrill wins outright; otherwise the row opens
             whatever its own first kebab action would — its "view info"
             destination — only when that action truly goes somewhere; a
             first action that's a copy or has no destination leaves the
             row inert rather than guessing at one. Clicking the kebab button
             or one of its own items still resolves to that item's own
             data-drill first (closest() finds it before ever reaching the
             row), so this never fights with the row's own menu. */
          const explicitD = rowD ? rowD(ri) : null;
          const first = items[0];
          const inferredD = !explicitD && first && first.d ? first.d : null;
          const attrObj = typeof rowAttr === 'function' ? rowAttr(ri) : (r._attr || null);
          const attrStr = attrObj ? Object.entries(attrObj).map(([k,v])=>`${k}="${esc(v)}"`).join(' ') : '';
          const rowClick = explicitD ? ` class="is-row-link"${dA(explicitD)}`
            : inferredD ? ` class="is-click"${dA(inferredD)}` : '';
          const combined = [attrStr, rowClick].filter(Boolean).join(' ');
          return `<tr${combined ? ' ' + combined : ''}>${r.map((c,i)=>{
            const kls = [cols[i].r ? 't-right num' : '', i === 0 && !cols[i].plain && STATUS_COL.test(cols[i].t) ? 'st-td' : ''].filter(Boolean).join(' ');
            return `<td${kls?` class="${kls}"`:''}>${c}</td>`; }).join('')}${menu?kebabCell(items,gid,ri):''}</tr>`;
        }).join('')
      : `<tr><td colspan="${span}" class="tbl-empty">No records match the current filter.</td></tr>`}</tbody>
  </table></div>`;
};

const bars = (rows, max, tone) => rows.map(r => {
  const inner = `<span class="vw-label">${r.n}</span>
    <div class="hbar-track"><div class="hbar-fill" style="width:${(r.c/max*100).toFixed(1)}%;background:${cv(tone||r.tone,400)}"></div></div>
    <span class="vw-value num t-right">${n(r.c)}</span>`;
  return r.d ? `<button class="hbar is-drill"${dA(r.d)}>${inner}</button>`
             : `<div class="hbar">${inner}</div>`;
}).join('');

const kpi = (label, value, sub, tone, d, isSelected) => {
  const colorStyle = tone ? `color:${cv(tone, 700)};` : '';
  const toneClass = tone ? ` stat-v--${tone}` : '';
  const inner = `<div class="vw-card-accent" style="background:${cv(tone||'cyan', 400)}"></div>
    <div class="vw-card-metric-label">${label}</div>
    <div class="vw-card-metric-xl num${toneClass}" style="${colorStyle}font-weight:500">${value}</div>
    <div class="vw-card-metric-label-sub">${sub}</div>`;
  const st = 'padding-top:calc(var(--vw-space-lg) + 3px);text-align:left;font:inherit;color:inherit;gap:var(--vw-space-xs)';
  const toneAttr = tone ? ` data-tone="${tone}"` : '';
  const selClass = isSelected ? ' is-selected' : '';
  const selAttr = isSelected ? ' data-selected="true" aria-current="true"' : '';
  return d
    ? `<button class="vw-card-section vw-card--clickable vw-card--accent stack-x is-drill${selClass}"${dA(d)}${toneAttr}${selAttr} style="${st}">${inner}</button>`
    : `<div class="vw-card-section vw-card--accent stack-x${selClass}"${toneAttr}${selAttr} style="${st}">${inner}</div>`;
};

/* ── drill-down plumbing ──────────────────────────────── */
let DRILL = null;                 /* { view, label, from } set by the router  */
/* d = { v:targetView, l:'human label', q:'key=value&key=value' } */
const dA = d => ` data-drill="${d.v}" data-dlabel="${esc(d.l)}"${d.q ? ` data-dq="${esc(d.q)}"` : ''}`;

/* Navigation is the topbar breadcrumb alone now — the in-page drill banner
   is retired. The function stays so every view's \${drillBar()} call keeps
   working; DRILL itself still drives filters and the URL's drill label. */
function drillBar() {
  return '';
}


/* funnel: [{n,v,sub,tone}] */
function funnel(rows, max) {
  return `<div class="stack-s">${rows.map((r,i) => {
    const w = (r.v/max*100);
    return `<div class="stack-x" style="gap:3px">
      <div class="row vw-justify-between" style="gap:var(--vw-space-sm)">
        <span class="vw-value" style="font-weight:500">${r.n}</span>
        <span class="vw-value num">${n(r.v)} <span class="vw-card-metric-label-sub">${r.unit}</span></span>
      </div>
      <div class="hbar-track" style="height:1.375rem">
        <div class="hbar-fill" style="width:${w.toFixed(1)}%;background:${cv(r.tone,300)}"></div>
      </div>
      <span class="vw-card-metric-label-sub">${r.sub}</span>
    </div>`;
  }).join('')}</div>`;
}

const ARROW = `<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M5 12h14M13 6l6 6-6 6"/></svg>`;

function donut(segs,total,top,sub,size=150){
  const sw=Math.max(7,Math.round(size*0.10)), r=size/2-sw/2-2, cx=size/2, cy=size/2, C=2*Math.PI*r;
  const fTop=Math.max(13,Math.round(size*0.145)), fSub=Math.max(10,Math.round(size*0.08));
  let off=0;
  const arcs=segs.map(s=>{const len=(s.c/total)*C;
    const el=`<circle cx="${cx}" cy="${cy}" r="${r}" fill="none" stroke="${cv(s.tone,400)}" stroke-width="${sw}"
      stroke-dasharray="${len.toFixed(2)} ${(C-len).toFixed(2)}" stroke-dashoffset="${(-off).toFixed(2)}"
      transform="rotate(-90 ${cx} ${cy})"><title>${s.n}: ${n(s.c)}</title></circle>`; off+=len; return el;}).join('');
  return `<svg viewBox="0 0 ${size} ${size}" style="height:${size}px;width:${size}px;flex-shrink:0;display:block" role="img" aria-label="${top} ${sub}">
    <circle cx="${cx}" cy="${cy}" r="${r}" fill="none" stroke="var(--vw-color-slate-100)" stroke-width="${sw}"/>${arcs}
    <text x="${cx}" y="${cy + (sub ? 0 : fTop*0.35)}" text-anchor="middle" font-size="${fTop}" font-weight="500" fill="var(--vw-color-slate-800, #1e293b)" font-family="Inter,sans-serif">${top}</text>
    ${sub ? `<text x="${cx}" y="${cy + fTop*0.78}" text-anchor="middle" font-size="${fSub}" fill="var(--vw-color-slate-500, #64748b)" font-family="Inter,sans-serif">${sub}</text>` : ''}</svg>`;
}

const legendRows = segs => `<div class="stack-x grow" style="gap:5px">${segs.map(s => {
  const inner = `<span class="legend-i"><span class="legend-sw" style="background:${cv(s.tone,400)}"></span>${s.n}</span>
    <span class="vw-value num">${n(s.c)}</span>`;
  return s.d ? `<button class="row vw-justify-between is-drill lg-row"${dA(s.d)} style="gap:var(--vw-space-sm)">${inner}</button>`
             : `<div class="row vw-justify-between" style="gap:var(--vw-space-sm)">${inner}</div>`;
}).join('')}</div>`;



/* ── copy-to-clipboard, with a fallback and visible confirmation ──
   navigator.clipboard.writeText() can reject silently (no document focus, no
   secure context, a permissions policy that blocks it) — the row action then
   looked broken because nothing ever told the reader it had failed. */
function copyFallback(value) {
  const ta = document.createElement('textarea');
  ta.value = value;
  ta.style.position = 'fixed'; ta.style.top = '0'; ta.style.left = '0'; ta.style.opacity = '0';
  document.body.appendChild(ta);
  ta.focus(); ta.select();
  try { document.execCommand('copy'); } catch (err) { /* nothing left to try */ }
  document.body.removeChild(ta);
}
function copyToClipboard(value) {
  if (navigator.clipboard && navigator.clipboard.writeText) {
    return navigator.clipboard.writeText(value).catch(() => copyFallback(value));
  }
  copyFallback(value);
  return Promise.resolve();
}
function showCopyToast(x, y, text, type) {
  const el = document.createElement('div');
  const isFail = type === 'error' || type === 'failed' ||
    (/\b(fail|failed|error|timeout|unreach|unreachable|denied|failure)\b/i.test(text) &&
     !/\b(success|successfully|verified|completed|applied|retried)\b/i.test(text));
  el.className = 'copy-toast ' + (isFail ? 'is-error' : 'is-success');
  el.textContent = text;

  // If explicitly requested on right or if x was passed as centered/notification coordinates
  const isCenter = typeof x === 'number' && Math.abs(x - (window.innerWidth / 2)) < 250;
  if (x === 'right' || x == null || isCenter) {
    el.classList.add('is-right');
    el.style.position = 'fixed';
    el.style.top = (y != null ? y : 72) + 'px';
    el.style.right = '24px';
    el.style.left = 'auto';
    el.style.transform = 'none';
  } else {
    el.style.left = x + 'px';
    el.style.top = y + 'px';
  }

  document.body.appendChild(el);
  requestAnimationFrame(() => el.classList.add('is-in'));
  setTimeout(() => {
    el.classList.remove('is-in');
    setTimeout(() => el.remove(), 200);
  }, 1400);
}
window.showCopyToast = showCopyToast;

/* ── currency ─────────────────────────────────────────── */
const inr = v => '₹' + Math.round(v).toLocaleString('en-IN');
const inrShort = v => v >= 1e7 ? '₹' + (v/1e7).toFixed(2) + ' Cr'
  : v >= 1e5 ? '₹' + (v/1e5).toFixed(2) + ' L' : '₹' + Math.round(v).toLocaleString('en-IN');

