/* grown after its own declaration — the eleven hand-written rows above stay
   for their narrative detail; the rest of "the 175 that failed" and "68 seen
   for the first time" (both quoted on Insights) are filled in here so the
   count on Scan targets is something you can actually open and read, in the
   exact reason mix the Insights donut and DROPS already state. */
(function growTargets() {
  let seed = 7919;
  const rnd = () => { seed = (seed * 48271) % 2147483647; return seed / 2147483647; };
  const pick = arr => arr[Math.floor(rnd() * arr.length)];
  const pad2 = v => String(v).padStart(2, '0');
  const flatten = mix => mix.flatMap(([k, c]) => Array(c).fill(k));

  const MODELS_BY_DOMAIN = {
    RAN: {
      Nokia: ['AirScale 5G', 'AirScale', 'AirScale gNB'],
      Ericsson: ['AIR 6449', 'Baseband 6630'],
      Huawei: ['AAU5613', 'BTS3900']
    },
    Core: {
      Nokia: ['AMF-CN', 'UPF-CN', 'SMF-CN', 'NRF-CN'],
      Ericsson: ['Cloud Core']
    },
    Transport: {
      Adva: ['FSP 3000'],
      Ciena: ['6500-T12'],
      Nokia: ['1830 PSS-32']
    },
    IPMPLS: {
      Juniper: ['MX960', 'MX204', 'ACX2200', 'ACX7024', 'EX4300-48P', 'EX2200-24T'],
      Cisco: ['ASR920', 'NCS-540', 'C9300-48UXM', 'C9400-LC-48T'],
      Nokia: ['7750', '7750 SR-7'],
      Adva: ['FSP 3000'],
      Edgecore: ['AS7712-32X']
    }
  };
  const ROLE_BY_DOMAIN = {
    RAN: ['GNB', 'ENB', 'BBU', 'RRU'],
    Core: ['AMF', 'UPF', 'SMF', 'NRF'],
    Transport: ['DWDM', 'ROADM', 'OTN', 'MUX'],
    IPMPLS: ['PE', 'AGG', 'ACC', 'CORE', 'EDGE', 'BNG']
  };

  /* Transport/IPMPLS jobs' scope is a real IP range ("172.31.75.0/24 ·
     172.31.79.255/24", i.e. the 3rd octet spans 75–79) or a seed address
     ("Seed 172.31.86.61 · depth 3") — a generated target assigned to one
     of these jobs has to land inside it, the same way a real scan would
     never report a device outside the range it was told to sweep. RAN/Core
     scope reads as a technology + site label ("gNodeB/eNodeB · Bengaluru-
     East"), not an address range, so neither pattern matches there and this
     returns null — the caller's own original formula runs unchanged, which
     is what keeps RAN/Core generation byte-for-byte untouched. */
  const scopeIpFor = (jobRow, i) => {
    const scope = jobRow.scope || '';
    const range = scope.match(/172\.31\.(\d+)\.\d+\/24\s*·\s*172\.31\.(\d+)\.\d+\/24/);
    if (range) {
      const lo = +range[1], hi = +range[2];
      return `172.31.${lo + (i % (hi - lo + 1))}.${10 + (i * 17) % 240}`;
    }
    const seed = scope.match(/Seed\s+(\d+)\.(\d+)\.(\d+)\.\d+/);
    if (seed) return `${seed[1]}.${seed[2]}.${seed[3]}.${10 + (i * 13) % 240}`;
    return null;
  };

  /* one row per unit of runFail, split across reasons exactly as DROPS states;
     the 5 hand-written failures above already carry one of each but dupip, so
     the generated share is trimmed by one apiece to land on 175 in total */
  const reasons = flatten([['unreach', 67], ['timeout', 40], ['auth', 32], ['adapter', 17], ['parse', 8], ['dupip', 6]]);

  /* IP/MPLS failures are real elements of the unified device repository (the
     same 239 the Insights failure grid lists): the address, and — where the
     device answered far enough to be named — the hostname, vendor, model and
     circle are the repository's, so a failed target here is findable by the same
     IP in Inventory. One failure per element; each reason draws from its own pool. */
  const masterPool = {};
  const haveIp = new Set(TARGETS.map(t => t.ip));
  if (typeof MASTER_FAILED !== 'undefined') MASTER_FAILED.filter(f => !haveIp.has(f.ip)).forEach(f => (masterPool[f.rk] = masterPool[f.rk] || []).push(f));
  const takeMaster = (reason, state) => {
    const pool = masterPool[reason] || [];
    const i = Math.max(0, pool.findIndex(f => f.ne.state === state));
    return pool.length ? pool.splice(i, 1)[0] : null;
  };

  reasons.forEach((reason, i) => {
    const circle = CIRCLES[i % CIRCLES.length];
    const jobRow = JOBS[i % JOBS.length];
    const job = jobRow.id;
    const dom = jobRow.domain || 'IPMPLS';
    const mf = dom === 'IPMPLS' ? takeMaster(reason, circle.n) : null;
    if (mf) {
      const known = reason !== 'unreach' && reason !== 'timeout';
      TARGETS.push({
        ip: mf.ip, host: known ? mf.ne.name : '—', oem: known ? mf.ne.oem : '—', model: known ? mf.ne.model : '—',
        circle: mf.ne.state, sync: getLiveDateSync(2 + i % 7, (i * 11) % 60),
        fresh: 1 + i % 18, job, domain: jobRow.domain,
        ch: chForDomain(['fail', 'na', 'na', 'na', 'na', 'na'], jobRow.domain), out: 'Missing', chip: 'error', reason
      });
      return;
    }
    const domModels = MODELS_BY_DOMAIN[dom] || MODELS_BY_DOMAIN.IPMPLS;
    const domOems = Object.keys(domModels);
    const oem = pick(domOems);
    const model = pick(domModels[oem]);
    const role = pick(ROLE_BY_DOMAIN[dom] || ROLE_BY_DOMAIN.IPMPLS);
    const known = reason !== 'unreach' && reason !== 'timeout';
    const host = known ? `${circle.c}-${model.replace(/[^A-Za-z0-9]/g, '').slice(0, 6).toUpperCase()}-${role}-${pad2(10 + i % 88)}` : '—';
    let targetIp = scopeIpFor(jobRow, i);
    if (!targetIp) {
      if (dom === 'RAN') {
        targetIp = role === 'ENB' ? `10.44.${10 + (i * 7) % 80}.${20 + (i * 13) % 230}` : `10.51.${10 + (i * 7) % 80}.${20 + (i * 13) % 230}`;
      } else if (dom === 'Core') {
        targetIp = `10.10.${10 + (i * 7) % 80}.${20 + (i * 13) % 230}`;
      } else if (dom === 'Transport') {
        targetIp = `172.31.${160 + (i * 7) % 38}.${20 + (i * 13) % 230}`;
      } else {
        targetIp = `172.31.${100 + (i * 7) % 40}.${20 + (i * 13) % 230}`;
      }
    }
    TARGETS.push({
      ip: targetIp,
      host, oem: known ? oem : '—', model: known ? model : '—',
      circle: circle.n, sync: getLiveDateSync(2 + i % 7, (i * 11) % 60),
      fresh: 1 + i % 18, job, domain: jobRow.domain,
      ch: chForDomain(['fail', 'na', 'na', 'na', 'na', 'na'], jobRow.domain), out: 'Missing', chip: 'error', reason
    });
  });

  /* devices seen for the first time this cycle: identified, not yet in
     Inventory — the two hand-written rows above are Rogue outcomes of the
     same shape, so the rest follow suit */
  for (let i = 0; i < 66; i++) {
    const circle = CIRCLES[(i + 5) % CIRCLES.length];
    const jobRow = JOBS[(i + 3) % JOBS.length];
    const job = jobRow.id;
    const dom = jobRow.domain || 'IPMPLS';
    const domModels = MODELS_BY_DOMAIN[dom] || MODELS_BY_DOMAIN.IPMPLS;
    const domOems = Object.keys(domModels);
    const oem = pick(domOems);
    const model = pick(domModels[oem]);
    const role = dom === 'RAN' ? (i % 2 === 0 ? 'GNB' : 'ENB') : 'NEW';
    let rogueIp = scopeIpFor(jobRow, i);
    if (!rogueIp) {
      if (dom === 'RAN') {
        rogueIp = role === 'ENB' ? `10.44.${30 + (i * 9) % 50}.${30 + (i * 17) % 210}` : `10.51.${30 + (i * 9) % 50}.${30 + (i * 17) % 210}`;
      } else if (dom === 'Core') {
        rogueIp = `10.10.${30 + (i * 9) % 50}.${30 + (i * 17) % 210}`;
      } else if (dom === 'Transport') {
        rogueIp = `172.31.${160 + (i * 9) % 38}.${30 + (i * 17) % 210}`;
      } else {
        rogueIp = `172.31.${100 + (i * 9) % 40}.${30 + (i * 17) % 210}`;
      }
    }
    TARGETS.push({
      ip: rogueIp,
      host: `${circle.c}-${model.replace(/[^A-Za-z0-9]/g, '').slice(0, 6).toUpperCase()}-${role}-${pad2(50 + i % 48)}`,
      oem, model, circle: circle.n,
      sync: getLiveDateSync(1 + i % 8, (i * 19) % 60),
      fresh: 1 + i % 12, job, domain: jobRow.domain,
      ch: chForDomain(i % 3 === 0 ? ['ok', 'ok', 'ok', 'na', 'na', 'na'] : ['ok', 'ok', 'ok', 'ok', 'na', 'na'], jobRow.domain),
      out: 'Rogue', chip: 'pink', isNew: true
    });
  }

  /* the hand-written rows above name a circle and, for IP/MPLS 'Missing' rows,
     an address from before the unified device repository existed. Where a
     target names a repository element its circle is that element's state; an
     IP/MPLS 'Missing' row (an element the network no longer answers for) is
     pinned to a real unreachable element, so every non-rogue IP/MPLS target
     resolves to an Inventory record by IP. 'Rogue' and 'Unclaimed' are the
     exceptions by definition — devices Discovery found that Inventory does not hold. */
  if (typeof MASTER_BY_NAME !== 'undefined') {
    TARGETS.forEach(t => {
      const m = t.host && t.host !== '—' ? MASTER_BY_NAME.get(String(t.host).toUpperCase()) : null;
      if (m && (m.ip === t.ip || m.ip2 === t.ip)) t.circle = m.state;
      else if (t.domain === 'IPMPLS' && t.out === 'Missing' && !MASTER_BY_IP.has(t.ip)) {
        const mf = takeMaster('unreach', t.circle);
        if (mf) { t.ip = mf.ip; t.circle = mf.ne.state; }
      }
    });
  }
})();


/* ═══ reporting period ═══════════════════════════════════
   The Insights period switch is global to the discovery and
   reconciliation module: every figure below is rewritten in
   place when the period changes, so no two screens can ever
   disagree about which window they are describing.

   Today  = the position at the close of the last cycle.
   7 / 30 = every element the window touched, counted at its
            last comparison inside it. A wider window sees
            more of the estate — elements added, retired, or
            reached only by a weekly job all fall inside it —
            so every bucket grows as the window widens and
            none of them can shrink. That is what the counts
            below assert, and what checkPeriods() enforces.
   ═══════════════════════════════════════════════════════ */
const PERIODS = [
  { k:'today', n:'Today',   cycles:1,  range:'01-Sep-2026',
    note:'Position at the close of the 01-Sep-2026 cycle.',
    runNote:'Outcome of the last run of each target.',
    recNote:'State of each element at the close of the cycle.' },
  { k:'d7', n:'7 days', cycles:7, range:'26-Aug – 01-Sep-2026',
    note:'Seven discovery cycles, 26-Aug to 01-Sep-2026.',
    runNote:'Every target polled in 7 cycles, at its last run.',
    recNote:'Every element compared in 7 cycles, at its last comparison.' },
  { k:'d30', n:'30 days', cycles:30, range:'03-Aug – 01-Sep-2026',
    note:'Thirty discovery cycles, 03-Aug to 01-Sep-2026.',
    runNote:'Every target polled in 30 cycles, at its last run.',
    recNote:'Every element compared in 30 cycles, at its last comparison.' }
];
let PERIOD = 'today';
let NAT_RATE = 0;
const pmeta = () => PERIODS.find(p => p.k === PERIOD) || PERIODS[0];

/* Each block is a closed ledger:
     targets      = runFull + runPartial + runFail
     master       = noCollector + discoverable
     discoverable = matched + missing
     matched      = exact + drifted + stale
     identified   = matched + rogue + unclaimed                       */
const DLP = {
  today: { targets:2308, runFull:1842, runPartial:291, runFail:175,
           master:2703, noCollector:206, discoverable:2497,
           matched:2379, missing:118, exact:1829, drifted:392, stale:158,
           rogue:160, unclaimed:64, identified:2603, discRouter:2212, discSwitch:391 },
  d7:    { targets:2371, runFull:1861, runPartial:320, runFail:190,
           master:2784, noCollector:209, discoverable:2575,
           matched:2447, missing:128, exact:1846, drifted:425, stale:176,
           rogue:172, unclaimed:70, identified:2689, discRouter:2285, discSwitch:404 },
  d30:   { targets:2468, runFull:1902, runPartial:358, runFail:208,
           master:2931, noCollector:214, discoverable:2717,
           matched:2572, missing:145, exact:1878, drifted:486, stale:208,
           rogue:194, unclaimed:82, identified:2848, discRouter:2419, discSwitch:429 }
};

/* freshness buckets — sum to identified in every period */
const FRESH_P = {
  today: [1142, 786, 402, 189, 84],
  d7:    [1168, 806, 418, 197, 100],
  d30:   [1224, 848, 446, 212, 118]
};
/* discovered devices by OEM — sum to identified in every period */
const OEM_P = {
  today: [1612, 806, 98, 54, 21, 12],
  d7:    [1657, 838, 102, 57, 22, 13],
  d30:   [1748, 886, 108, 61, 25, 20]
};
const OEM_ROWS = [
  { n:'Juniper', tone:'sky' }, { n:'Cisco', tone:'cyan' }, { n:'Cisco SDN', tone:'indigo' },
  { n:'Nokia', tone:'purple' }, { n:'Adva', tone:'amber' }, { n:'Edgecore', tone:'slate' }
];
/* collector families — ok + fail + na sum to targets in every period */
const COLL_P = {
  today: [[2133,175,0],[2041,92,175],[2098,35,175],[1412,63,833],[604,21,1683],[1289,47,972]],
  d7:    [[2181,190,0],[2085,96,190],[2144,37,190],[1447,66,858],[619,23,1729],[1321,50,1000]],
  d30:   [[2260,208,0],[2159,101,208],[2221,39,208],[1502,70,896],[645,26,1797],[1375,53,1040]]
};

/* what moved inside the window — regressions against recoveries */
const MOVE_P = {
  today: [
    { n:'Records added',        v:14,  dir:'up',   tone:'sky' },
    { n:'Records retired',      v:6,   dir:'down', tone:'slate' },
    { n:'Newly drifted',        v:38,  dir:'bad',  tone:'amber' },
    { n:'Drift resolved',       v:51,  dir:'good', tone:'emerald' },
    { n:'Stopped answering',    v:9,   dir:'bad',  tone:'red' },
    { n:'Answered again',       v:4,   dir:'good', tone:'emerald' }
  ],
  d7: [
    { n:'Records added',        v:63,  dir:'up',   tone:'sky' },
    { n:'Records retired',      v:25,  dir:'down', tone:'slate' },
    { n:'Newly drifted',        v:187, dir:'bad',  tone:'amber' },
    { n:'Drift resolved',       v:154, dir:'good', tone:'emerald' },
    { n:'Stopped answering',    v:41,  dir:'bad',  tone:'red' },
    { n:'Answered again',       v:18,  dir:'good', tone:'emerald' }
  ],
  d30: [
    { n:'Records added',        v:148, dir:'up',   tone:'sky' },
    { n:'Records retired',      v:45,  dir:'down', tone:'slate' },
    { n:'Newly drifted',        v:612, dir:'bad',  tone:'amber' },
    { n:'Drift resolved',       v:498, dir:'good', tone:'emerald' },
    { n:'Stopped answering',    v:129, dir:'bad',  tone:'red' },
    { n:'Answered again',       v:44,  dir:'good', tone:'emerald' }
  ]
};

/* ── proportional rescale that always closes on the total ── */
const SNAP = {
  circles: CIRCLES.map(c => ({ master:c.master, rogue:c.rogue, missing:c.missing, drift:c.drift })),
  drops:   DROPS.map(d => d.n),
  rules:   MATCH_RULES.map(r => r.hits),
  seen:    TAXONOMY.map(t => t.seen),
  drift:   DRIFT_BY_FIELD.map(d => d.c)
};
function spread(src, total) {
  const cur = src.reduce((a, b) => a + b, 0);
  if (!cur || !total) return src.map(() => 0);
  const out = src.map(v => Math.round(v / cur * total));
  let diff = total - out.reduce((a, b) => a + b, 0);
  if (diff) { let bi = 0; out.forEach((v, i) => { if (v > out[bi]) bi = i; }); out[bi] += diff; }
  return out;
}

/* Four parallel number tables kept by hand is exactly how a window ends up
   claiming fewer records than a narrower one. Each is a closed ledger, and
   widening the window may only ever add — so both are asserted here rather
   than trusted. */
function checkPeriods() {
  const order = ['today', 'd7', 'd30'];
  const sum = a => a.reduce((x, y) => x + y, 0);
  const bad = m => { throw new Error('period ledger: ' + m); };

  order.forEach(k => {
    const d = DLP[k];
    if (d.runFull + d.runPartial + d.runFail !== d.targets) bad(`${k} run outcomes ≠ targets`);
    if (d.exact + d.drifted + d.stale !== d.matched)        bad(`${k} match states ≠ matched`);
    if (d.matched + d.missing !== d.discoverable)           bad(`${k} matched + missing ≠ discoverable`);
    if (d.noCollector + d.discoverable !== d.master)        bad(`${k} discoverable + no-collector ≠ master`);
    if (d.matched + d.rogue + d.unclaimed !== d.identified) bad(`${k} matched + rogue + unclaimed ≠ identified`);
    if (d.discRouter + d.discSwitch !== d.identified)       bad(`${k} classes ≠ identified`);
    if (sum(FRESH_P[k]) !== d.identified)                   bad(`${k} freshness ≠ identified`);
    if (sum(OEM_P[k]) !== d.identified)                     bad(`${k} OEM split ≠ identified`);
    COLL_P[k].forEach((row, i) => { if (sum(row) !== d.targets) bad(`${k} collector ${i} ≠ targets`); });
  });

  /* nothing a window counts may fall as the window widens */
  const rises = (label, of) => order.slice(1).forEach((k, i) => {
    const prev = of(order[i]), now = of(k);
    if (now < prev) bad(`${label} falls from ${order[i]} (${prev}) to ${k} (${now})`);
  });
  Object.keys(DLP.today).forEach(f => rises(f, k => DLP[k][f]));
  FRESH_P.today.forEach((_, i) => rises(`freshness[${i}]`, k => FRESH_P[k][i]));
  OEM_P.today.forEach((_, i) => rises(`oem[${i}]`, k => OEM_P[k][i]));
  COLL_P.today.forEach((_, i) => {
    rises(`collector[${i}].ok`, k => COLL_P[k][i][0]);
    rises(`collector[${i}].fail`, k => COLL_P[k][i][1]);
  });
  MOVE_P.today.forEach((m, i) => rises(`moved · ${m.n}`, k => MOVE_P[k][i].v));
}

function applyPeriod() {
  Object.assign(DL, DLP[PERIOD]);
  DL.union = DL.master + DL.rogue + DL.unclaimed;
  DL.open  = DL.drifted + DL.missing + DL.rogue + DL.unclaimed;

  FRESH_P[PERIOD].forEach((c, i) => { FRESHNESS[i].c = c; });
  COLL_P[PERIOD].forEach(([ok, fail, na], i) =>
    Object.assign(COLLECTORS[i], { ok, fail, na }));

  spread(SNAP.drops, DL.runFail).forEach((v, i) => { DROPS[i].n = v; });
  spread(SNAP.rules, DL.identified - DL.unclaimed).forEach((v, i) => { MATCH_RULES[i].hits = v; });
  spread(SNAP.drift, DL.drifted).forEach((v, i) => { DRIFT_BY_FIELD[i].c = v; });

  /* circle exceptions must add up to the placed (identifiable) open items */
  const placed = DL.open - DL.unclaimed;
  const wt = SNAP.circles.map(c => c.rogue + c.missing + c.drift);
  const each = spread(wt, placed);
  CIRCLES.forEach((c, i) => {
    const s = SNAP.circles[i], w = s.rogue + s.missing + s.drift || 1;
    c.master  = Math.round(s.master * DL.master / DLP.today.master);
    c.rogue   = Math.round(each[i] * s.rogue / w);
    c.missing = Math.round(each[i] * s.missing / w);
    c.drift   = each[i] - c.rogue - c.missing;
    c.exc     = c.rogue + c.missing + c.drift;
    c.sites   = Math.max(1, Math.round(c.master * IL.locations / DLP.today.master));
    c.verified= Math.max(0, c.master - c.missing);
    c.rate    = c.master ? c.exc / c.master * 100 : 0;
    c.job     = `DSC-${c.c}-EDGE`;
  });
  NAT_RATE = DL.master ? (DL.open - DL.unclaimed) / DL.master * 100 : 0;

  /* what each class was seen on the network at least once in the window */
  const r = DL.identified / DLP.today.identified;
  TAXONOMY.forEach((t, i) => { t.seen = SNAP.seen[i] ? Math.min(t.master, Math.round(SNAP.seen[i] * r)) : 0; });

  /* the six outcome rows are the same ledger, re-cut */
  OUTCOME.forEach(o => { o.c = DL[o.k]; });

  /* reconciliation bands are the same ledger, re-cut */
  REC_BANDS.invOnly.c = DL.missing;
  REC_BANDS.both.c    = DL.matched;
  REC_BANDS.both.parts[0].c = DL.exact;
  REC_BANDS.both.parts[1].c = DL.drifted;
  REC_BANDS.both.parts[2].c = DL.stale;
  REC_BANDS.netOnly.c = DL.rogue + DL.unclaimed;
  REC_BANDS.netOnly.parts[0].c = DL.rogue;
  REC_BANDS.netOnly.parts[1].c = DL.unclaimed;
  REC_BANDS.notComparable.c = DL.noCollector;
}
checkPeriods();
applyPeriod();

/* ═══ grid chrome: row kebab menus, toolbar, filter panel ═══ */
const IC_SEARCH = `<svg viewBox="0 0 24 24" width="15" height="15" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><circle cx="11" cy="11" r="7"/><path d="M20 20l-3.5-3.5"/></svg>`;
const IC_FILTER = `<svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="M3 5h18l-7 8v6l-4 2v-8z"/></svg>`;
const IC_KEBAB  = `<svg viewBox="0 0 24 24" width="16" height="16" fill="currentColor"><circle cx="12" cy="5" r="1.7"/><circle cx="12" cy="12" r="1.7"/><circle cx="12" cy="19" r="1.7"/></svg>`;
const IC_REFRESH = `<svg viewBox="0 0 16 16" width="16" height="16" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"><path d="M14 8a6 6 0 1 1-1.9-4.4"/><path d="M14 2v3.6h-3.6"/></svg>`;
const IC_X      = `<svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"><path d="M6 6l12 12M18 6L6 18"/></svg>`;

let KEBAB = null;          /* "<gridId>:<rowIndex>" of the open row menu */
let GRIDMENU = false;      /* the toolbar's own overflow menu            */
let FILTER_OPEN = false;   /* the Filters panel                          */
let FILTER_FIELD = 0;
let CHIPS_MODAL = null;    /* grid key whose "+N more" chip popup is open */
let GRID_N = 0;            /* reset each render so grid ids are stable   */

/* ── search + filters, per grid ───────────────────────────
   Keyed by the grid's own key (one per screen). A grid's search box and
   filter panel write into this; the view reads it back through gridApply()
   before it builds its rows, so both actually narrow what's on screen. */
let GRID_STATE = {};
const gridOf = key => GRID_STATE[key] || (GRID_STATE[key] = { search: '', filters: {} });
/* No per-grid field mapping to keep in sync: a row matches if the query (or
   every active filter value) appears anywhere in that row's own data. */
function getLegacyFieldValue(r, field) {
  if (!r || typeof r !== 'object') return '';
  const f = field.toLowerCase().trim();

  if (f === 'status' || f === 'state' || f === 'outcome' || f === 'result') {
    if (r.st) {
      if (typeof RSTATE !== 'undefined' && RSTATE[r.st]) return RSTATE[r.st][0];
      if (typeof lst !== 'undefined' && lst[r.st]) return lst[r.st][0];
      return String(r.st);
    }
    if (r.status) return String(r.status);
    /* JOBS rows carry their run status as `.state` ('Completed', 'Completed
       with errors', 'Running', 'No adapter') rather than `.st` — without
       this branch the Status filter fell through to a whole-row substring
       search, which also let "Completed" silently match "Completed with
       errors" (see the `exact` check below, which now covers this field too) */
    if (r.state) return String(r.state);
    if (r.outcome) return String(r.outcome);
    if (r.result) return String(r.result);
    if (r.res) return String(r.res);
  }

  if (f === 'stock state' || f === 'stock') {
    if (r.stock && typeof stockMeta !== 'undefined') return stockMeta(r.stock).n;
    if (r.stock) return String(r.stock);
  }

  if (f === 'source') {
    if (r.s && typeof SRC !== 'undefined' && SRC[r.s]) return SRC[r.s][0];
    if (r.source) return String(r.source);
  }

  if (f === 'domain' && r.domain && typeof DOMAIN_META !== 'undefined' && DOMAIN_META[r.domain]) {
    return DOMAIN_META[r.domain].n;
  }

  /* Scan Targets' Age filter options ('Under 24 h', '1 – 7 days', ...) never
     appear verbatim in a target row — only the raw `.fresh` hour count does
     — so without this bucketing the filter always matched nothing. Same
     boundaries freshChip() already renders the Age column with (24h/7d/30d),
     so the filter option a reader picks always matches what the column shows. */
  if (f === 'age' && typeof r.fresh === 'number') {
    if (r.fresh < 24) return 'Under 24 h';
    if (r.fresh < 168) return '1 – 7 days';
    if (r.fresh < 720) return '7 – 30 days';
    return 'Over 30 days';
  }

  for (const [k, v] of Object.entries(r)) {
    const kClean = k.toLowerCase().replace(/[^a-z0-9]/g, '');
    const fClean = f.replace(/[^a-z0-9]/g, '');
    if (kClean === fClean) return String(v);
  }

  return '';
}

function gridApply(key, rows) {
  const st = gridOf(key);
  const q = st.search.trim().toLowerCase();
  const need = Object.entries(st.filters).filter(([, v]) => v && String(v).trim() !== '');
  if (!q && !need.length) return rows;

  return rows.filter(r => {
    let text = JSON.stringify(r).toLowerCase();
    if (r && typeof r === 'object') {
      if (r.st) {
        if (typeof RSTATE !== 'undefined' && RSTATE[r.st]) text += ' ' + RSTATE[r.st][0].toLowerCase();
        if (typeof lst !== 'undefined' && lst[r.st]) text += ' ' + lst[r.st][0].toLowerCase();
      }
      if (r.stock && typeof stockMeta !== 'undefined') text += ' ' + stockMeta(r.stock).n.toLowerCase();
      if (r.s && typeof SRC !== 'undefined' && SRC[r.s]) text += ' ' + SRC[r.s][0].toLowerCase();
    }

    if (q && !text.includes(q)) return false;

    for (const [field, fVal] of need) {
      const v = String(fVal).trim().toLowerCase();
      if (!v) continue;
      const fieldVal = getLegacyFieldValue(r, field).toLowerCase();
      if (fieldVal) {
        /* "RAN" is a substring of "Transport", and "Completed" is a prefix
           of "Completed with errors" — categorical fields like Domain and
           Status, whose options are a fixed enum rather than free text,
           need an exact match or filtering one option silently pulls in
           any other option whose text contains it */
        if (field.toLowerCase() === 'domain' && r.domain && typeof domainFilterMatch === 'function') {
          /* Domain is a tree: 'Transport' keeps its IP/MPLS sub-domain rows */
          if (!domainFilterMatch(r.domain, v)) return false;
          continue;
        }
        const exact = field.toLowerCase() === 'domain' || field.toLowerCase() === 'status';
        if (exact ? fieldVal !== v : !fieldVal.includes(v)) return false;
      } else {
        if (!text.includes(v)) return false;
      }
    }

    return true;
  });
}

/* one action: A('Label') or A('Label', {v,l,q}) or A('Label', null, true) for danger */
/* Row actions carry a leading icon, as the platform grids do. The icon is
   inferred from the verb so no call site has to name one. */
const KI = {
  view:  '<path d="M1 8s2.5-4.5 7-4.5S15 8 15 8s-2.5 4.5-7 4.5S1 8 1 8Z"/><circle cx="8" cy="8" r="2"/>',
  life:  '<path d="M2 4h5M11 4h3M2 8h9M13 8h1M2 12h3M8 12h6"/><circle cx="9" cy="4" r="1.6"/><circle cx="12.4" cy="8" r="1.6"/><circle cx="6" cy="12" r="1.6"/>',
  jobs:  '<rect x="2" y="2.5" width="12" height="11" rx="1.5"/><path d="M5 6h6M5 9h6M5 11.5h3"/>',
  open:  '<path d="M9 2h5v5M14 2 7.5 8.5"/><path d="M12 9.5V13a1 1 0 0 1-1 1H3a1 1 0 0 1-1-1V5a1 1 0 0 1 1-1h3.5"/>',
  run:   '<path d="M14 8a6 6 0 1 1-1.8-4.3"/><path d="M14 2v3.5h-3.5"/>',
  copy:  '<rect x="5.5" y="5.5" width="8" height="8" rx="1.5"/><path d="M10.5 5.5V4a1.5 1.5 0 0 0-1.5-1.5H4A1.5 1.5 0 0 0 2.5 4v5A1.5 1.5 0 0 0 4 10.5h1.5"/>',
  down:  '<path d="M8 2v8M4.5 7 8 10.5 11.5 7M2.5 13.5h11"/>',
  undo:  '<path d="M3 8a5.5 5.5 0 1 0 1.6-3.9"/><path d="M2 2.5V6h3.5"/>',
  del:   '<path d="M2.5 4.5h11M6 4.5V3h4v1.5M4 4.5l.7 9h6.6l.7-9"/>',
  add:   '<path d="M8 3v10M3 8h10"/>',
  print: '<path d="M4.5 6V2.5h7V6M4.5 12.5h7V10h-7Z"/><rect x="2" y="6" width="12" height="4.5" rx="1"/>',
  cal:   '<rect x="2" y="3" width="12" height="11" rx="1.5"/><path d="M2 6.5h12M5.5 2v2M10.5 2v2"/>',
  cols:  '<rect x="2" y="3" width="12" height="10" rx="1.5"/><path d="M6.5 3v10M10 3v10"/>',
  opts:  '<path d="M2 4.5h7M12 4.5h2M2 8h2M7 8h7M2 11.5h9"/><circle cx="10.5" cy="4.5" r="1.6"/><circle cx="5.5" cy="8" r="1.6"/><circle cx="12.5" cy="11.5" r="1.6"/>',
  save:  '<path d="M3 2.5h8L13.5 5v8.5a1 1 0 0 1-1 1h-9a1 1 0 0 1-1-1v-10a1 1 0 0 1 1-1Z"/><path d="M5 2.5v4h6"/>',
  node:  '<rect x="4" y="4" width="8" height="8" rx="1.5"/><path d="M6.5 1.5v2.5M9.5 1.5v2.5M6.5 12v2.5M9.5 12v2.5M1.5 6.5H4M1.5 9.5H4M12 6.5h2.5M12 9.5h2.5"/>',
  file:  '<path d="M9 2H4.5a1 1 0 0 0-1 1v10a1 1 0 0 0 1 1h7a1 1 0 0 0 1-1V5.5Z"/><path d="M9 2v3.5h3.5"/>',
  pin:   '<path d="M8 14s5-4.4 5-8A5 5 0 0 0 3 6c0 3.6 5 8 5 8Z"/><circle cx="8" cy="6" r="1.8"/>'
};
const kiFor = l => {
  const t = String(l).toLowerCase();
  if (/node view|hardware/.test(t)) return KI.node;
  if (/life ?cycle|change|edit|rename|assign|stock state/.test(t)) return KI.life;
  if (/job|history|log|audit|workorder/.test(t)) return KI.jobs;
  if (/re-?run|run now|re-?reconcile|refresh|survey|test/.test(t)) return KI.run;
  if (/retry|probe|re-probe/.test(t)) return KI.run;
  if (/remediat|fix|repair/.test(t)) return KI.opts;
  if (/copy/.test(t)) return KI.copy;
  if (/download|export|report/.test(t)) return KI.down;
  if (/restore|recover|revert/.test(t)) return KI.undo;
  if (/create|new |add|instantiate|generate/.test(t)) return KI.add;
  if (/print|label/.test(t)) return KI.print;
  if (/schedule/.test(t)) return KI.cal;
  if (/table option|setting|preference/.test(t)) return KI.opts;
  if (/column/.test(t)) return KI.cols;
  if (/save/.test(t)) return KI.save;
  if (/site|location/.test(t)) return KI.pin;
  if (/import|attach|credential|collector/.test(t)) return KI.file;
  if (/open|go to|topology|reconcil/.test(t)) return KI.open;
  return KI.view;
};
const kIcon = l => `<svg class="kmi" viewBox="0 0 16 16" width="15" height="15" fill="none"
  stroke="currentColor" stroke-width="1.3" stroke-linecap="round" stroke-linejoin="round">${kiFor(l)}</svg>`;
const A = (l, d, danger) => ({ l, d, danger });
/* A row action that copies one of the row's own values. Every menu item on a
   screen either goes somewhere or does something — nothing is listed that only
   closes the menu again. */
const CP = (l, v) => ({ l, copy: v });

function kebabCell(items, gid, i) {
  const open = KEBAB === `${gid}:${i}`;
  if (!items.length) return '<td class="kb-td"></td>';
  return `<td class="kb-td">
    <button class="kb${open ? ' is-on' : ''}" data-kebab="${gid}:${i}" aria-label="Row actions"
      aria-expanded="${open}">${IC_KEBAB}</button>
    ${open ? `<div class="kmenu">${items.map(it =>
      `<button type="button" class="kmenu-i${it.danger ? ' is-danger' : ''}"${it.d ? dA(it.d) : ''}${
        it.copy ? ` data-copy="${esc(String(it.copy))}"` : ''}${
        it.linkview ? ` data-linkview="${esc(it.linkview)}"` : ''}${
        it.remediateIp ? ` data-remediate-ip="${esc(it.remediateIp)}"` : ''}${
        it.retryIp ? ` data-retry-ip="${esc(it.retryIp)}"` : ''}${
        it.svcview ? ` data-svcview="${esc(it.svcview)}"` : ''}>${kIcon(it.l)}<span>${it.l}</span></button>`).join('')}</div>` : ''}
  </td>`;
}

/* ── toolbar ───────────────────────────────────────────── */
/* extra: quick-filter controls (segmented tabs, a "Run now" button, …) that
   sit left of the search box's grow spacer.
   filterChips: one removable chip per value the Filters panel currently
   holds — sits on the right, right against the funnel icon it explains,
   rather than competing with extra's own controls for the left side. */
function gridBar(showing, total, placeholder, spec, extra = '', acts = [], key = '', filterChips = '') {
  const st = gridOf(key);
  const activeFilters = Object.entries(st.filters).filter(([k, v]) => Boolean(v) && (!['jobs', 'targets'].includes(key) || k !== 'Domain')).length;
  return `<div class="grid-bar">
    <span class="vw-card-description grid-count">${showing === null
      ? `<span class="num">${total}</span> records` : `Showing ${showing} of ${total}`}</span>
    <span class="nst-input-shell grid-search"><span class="gs-ic">${IC_SEARCH}</span>
      <input class="nst-input" placeholder="${placeholder}" aria-label="Search" data-gridsearch="${key}" value="${esc(st.search)}"></span>
    ${extra}
    <span class="grow"></span>
    ${filterChips}
    <div class="grid-tools">
      <button class="icon-btn${FILTER_OPEN ? ' is-on' : ''}${activeFilters ? ' has-value' : ''}" data-filteropen="${key}" aria-label="Filters"
        aria-expanded="${FILTER_OPEN}">${IC_FILTER}</button>
      <button class="icon-btn${GRIDMENU ? ' is-on' : ''}" data-gridmenu="1" aria-label="More actions"
        aria-expanded="${GRIDMENU}">${IC_KEBAB}</button>
      ${GRIDMENU ? `<div class="kmenu kmenu-r">
        ${acts.length ? acts.map(a => `<button class="kmenu-i${a.primary ? ' is-primary' : ''}${(a.d || a.nav) ? '' : ' js-ack'}"${a.d ? dA(a.d) : ''}${
          a.nav ? ` data-nav="${a.nav}"` : ''}>${kIcon(a.l)}<span>${a.l}</span></button>`).join('') + '<div class="kmenu-sep"></div>' : ''}
        <button class="kmenu-i" data-gridrefresh="1">${kIcon('Refresh')}<span>Refresh</span></button>
        <button class="kmenu-i" data-gridexport="${key}|csv">${kIcon('Export as CSV')}<span>Export as CSV</span></button>
        <button class="kmenu-i" data-gridexport="${key}|xlsx">${kIcon('Export as XLSX')}<span>Export as XLSX</span></button></div>` : ''}
      ${FILTER_OPEN ? filterPanel(spec, key) : ''}
    </div>
    ${CHIPS_MODAL === key ? chipsModal(key) : ''}
  </div>`;
}

/* ── filter panel ──────────────────────────────────────── */
function filterPanel(spec, key = '') {
  const fields = spec && spec.length ? spec : [{ n: 'Status', o: ['On-air', 'Planned'] }];
  const f = fields[Math.min(FILTER_FIELD, fields.length - 1)];
  const val = gridOf(key).filters[f.n] || '';
  return `<div class="fpanel" role="dialog" aria-label="Filters">
    <div class="fpanel-head">
      <span class="vw-card-title-sm">Filters</span>
      <button class="fp-x" data-filterclose="1" aria-label="Close">${IC_X}</button>
    </div>
    <div class="fpanel-body">
      <div class="fpanel-nav">
        ${fields.map((x, i) => `<button class="fp-f${i === FILTER_FIELD ? ' is-on' : ''}${gridOf(key).filters[x.n] ? ' has-value' : ''}"
          data-filterfield="${key}|${i}">${x.n}</button>`).join('')}
      </div>
      <div class="fpanel-ctl">
        <span class="fp-label">${f.n}</span>
        ${f.o
          ? `<span class="nst-select-shell"><select class="nst-input fp-sel${val ? '' : ' is-placeholder'}" data-filterval="${key}|${esc(f.n)}" placeholder="${esc(f.n)}">
               <option value=""${val ? '' : ' selected'}>${esc(f.n)}</option>
               ${f.o.map(o => {
                 const ov = (typeof o === 'object' && o !== null) ? o.v : o;
                 const ol = (typeof o === 'object' && o !== null) ? (o.l || o.v) : o;
                 return `<option value="${esc(ov)}"${ov === val ? ' selected' : ''}>${esc(ol)}</option>`;
               }).join('')}</select></span>`
          : `<span class="nst-input-shell"><input class="nst-input" placeholder="${esc(f.n)}" data-filterval="${key}|${esc(f.n)}" value="${esc(val)}"></span>`}
        ${f.h ? `<span class="fp-hint">${f.h}</span>` : ''}
      </div>
    </div>
    <div class="fpanel-foot">
      <span class="grow"></span>
      <button class="nst-btn nst-btn--sm" data-filterreset="${key}">Reset to default</button>
      <button class="nst-btn nst-btn--sm fp-apply" data-filterapply="${key}">Apply filters</button>
    </div>
  </div>`;
}

/* ── chip-row overflow ─────────────────────────────────────
   A `.stock-chips` row (the Type/quick chips plus one chip per active
   filter) runs single-line, never wrapping the toolbar onto a third line
   as more filters land. Whatever doesn't fit collapses behind a "+N More"
   chip (built here, not in any view's template — how many fit is a layout
   fact go() can't know until the row is painted); clicking it opens
   chipsModal() below, which lists every applied filter regardless of which
   ones actually overflowed. Re-run after every go() and on resize, since
   both can change how many chips fit. */
let STOCKCHIPS_BOUND = false;
function layoutStockChips() {
  if (!STOCKCHIPS_BOUND) { STOCKCHIPS_BOUND = true; window.addEventListener('resize', layoutStockChips); }
  document.querySelectorAll('.stock-chips').forEach(row => {
    const key = row.dataset.chipsrow || '';
    const old = row.querySelector('.stock-chip-more');
    if (old) old.remove();
    const chips = Array.from(row.children);
    chips.forEach(c => c.classList.remove('is-chip-hidden'));
    if (row.scrollWidth <= row.clientWidth + 1) return;

    const more = document.createElement('button');
    more.type = 'button';
    more.className = 'vw-chip vw-chip--neutral stock-chip stock-chip-more';
    more.dataset.chipsmore = key;
    row.appendChild(more);

    /* the first chip (always "All") stays put as the row's anchor — only
       the tail collapses, most-recently-added filter first */
    let hidden = 0;
    for (let i = chips.length - 1; i >= 1 && row.scrollWidth > row.clientWidth; i--) {
      chips[i].classList.add('is-chip-hidden');
      hidden++;
    }
    if (!hidden) { more.remove(); return; }
    more.textContent = `+ ${hidden} More`;
    more.setAttribute('aria-label', `Show all applied filters (${hidden} more)`);
  });
}

/* ── "selected filters" popup ─────────────────────────────
   Opened from the chip row's "+N More" chip. Rather than reveal just the
   overflowed chips in place (which would still push the page around every
   time the set of filters changes), it lists every filter this grid has
   applied — field and value both live in gridOf(key).filters already, so
   nothing view-specific is needed here. */
function chipsModal(key) {
  const active = Object.entries(gridOf(key).filters).filter(([k, v]) => Boolean(v) && (!['jobs', 'targets'].includes(key) || k !== 'Domain'));
  return `<div class="drawer-overlay" data-chipsmodalclose="1"></div>
    <div class="chips-modal" role="dialog" aria-label="Selected filters">
      <div class="chips-modal-head">
        <span class="vw-card-title-sm">Selected filters</span>
        <button class="fp-x" data-chipsmodalclose="1" aria-label="Close">${IC_X}</button>
      </div>
      <div class="chips-modal-meta">
        <span>${active.length} filter${active.length === 1 ? '' : 's'} applied</span>
        ${active.length ? `<button class="chips-modal-clear" data-filterreset="${key}">Remove all</button>` : ''}
      </div>
      <div class="chips-modal-list">
        ${active.length ? active.map(([field, value]) => `<span class="vw-chip vw-chip--neutral active-filter-chip">${esc(field)} = ${esc(value)}
          <button class="active-filter-chip-x" data-clearfilter="${key}|${esc(field)}" aria-label="Remove ${esc(field)} filter">${IC_X}</button></span>`).join('')
          : `<span class="chips-modal-empty">No filters applied.</span>`}
      </div>
    </div>`;
}

/* ── active-filter chip row ────────────────────────────────
   A plain "one chip per active filter" row for any grid whose toolbar has
   no quick-filter buttons of its own to build a richer chip row around
   (viewVirtual's Type row is the one exception, and builds its own inline).
   Feeds the same layoutStockChips()/chipsModal() overflow handling as that
   row, via the shared .stock-chips/data-chipsrow markup. */
function activeFilterChips(key) {
  const filters = gridOf(key).filters;
  const chips = Object.entries(filters).filter(([k, v]) => Boolean(v) && (!['jobs', 'targets'].includes(key) || k !== 'Domain'))
    .map(([field, value]) => `<span class="vw-chip vw-chip--info active-filter-chip">${esc(field)}: ${esc(value)}
      <button class="active-filter-chip-x" data-clearfilter="${key}|${esc(field)}" aria-label="Remove ${esc(field)} filter">${IC_X}</button></span>`)
    .join('');
  return chips ? `<div class="stock-chips" data-chipsrow="${esc(key)}">${chips}</div>` : '';
}

