/* ── map state selection ──────────────────────────────── */
/* One path for every way a state can be chosen — boundary click, cluster
   pin, dropdown — so the outline, the panel and the filter can't drift
   apart. code = circle code, or null/'' for the all-India rollup. */
function syncMapSel() {
  document.querySelectorAll('path.st').forEach(x => {
    const on = !!LOC_SEL && x.dataset.circle === LOC_SEL;
    x.classList.toggle('is-sel', on);
    x.setAttribute('stroke', on ? 'var(--vw-color-gray-900)' : 'var(--vw-color-white)');
    x.setAttribute('stroke-width', on ? 2.4 : 0.9);
  });
}
function selectMapState(code) {
  LOC_SEL = code || null;
  PIN_GROUP = null;
  syncMapSel();
  const p = document.getElementById('mappanel');
  if (p) p.innerHTML = mapPanel();
}

/* ── map pan / zoom ───────────────────────────────────── */
let MZ = { k: 1, x: 0, y: 0 };
/* Unbounded pan/zoom can carry the whole map off-canvas and leave it looking
   blank with nothing left to click back to. Keep a slice always on screen. */
function clampMZ() {
  const sx = GEO.W * 0.4, sy = GEO.H * 0.4;
  MZ.x = Math.min(GEO.W - sx, Math.max(sx - GEO.W * MZ.k, MZ.x));
  MZ.y = Math.min(GEO.H - sy, Math.max(sy - GEO.H * MZ.k, MZ.y));
}
function applyMZ() {
  const g = document.getElementById('mapzoom');
  if (g) g.setAttribute('transform', `translate(${MZ.x} ${MZ.y}) scale(${MZ.k})`);
}
function mapZoom(dir) {
  const svg = document.getElementById('mapsvg'); if (!svg) return;
  if (dir === 'reset') { MZ = { k:1, x:0, y:0 }; return applyMZ(); }
  const f = dir === 'in' ? 1.35 : 1/1.35, k2 = Math.min(8, Math.max(1, MZ.k * f));
  const cx = GEO.W/2, cy = GEO.H/2;
  MZ.x = cx - (cx - MZ.x) * (k2 / MZ.k);
  MZ.y = cy - (cy - MZ.y) * (k2 / MZ.k);
  MZ.k = k2; clampMZ(); applyMZ(); repin();
}
function repin() {
  const g = document.getElementById('mapzoom'); if (!g || CURRENT !== 'location' || LOC_VIEW !== 'map') return;
  const svg = document.getElementById('mapsvg');
  const t = g.getAttribute('transform');
  svg.outerHTML = mapSvg();
  const g2 = document.getElementById('mapzoom'); if (g2) g2.setAttribute('transform', t);
  const s2 = document.getElementById('mapsvg'); if (s2) { s2.dataset.bound = ''; bindMap(); }
}
function bindMap() {
  const svg = document.getElementById('mapsvg'); if (!svg || svg.dataset.bound) return;
  svg.dataset.bound = '1';
  let drag = null;
  /* Capture only once a real drag starts. Capturing already on pointerdown
     makes the browser retarget pointerup to the svg, and the compatibility
     click event then fires on the svg instead of the state path under the
     pointer — which silently kills state selection. A small movement
     threshold is what separates a click from a pan. */
  svg.addEventListener('pointerdown', e => { drag = { x:e.clientX, y:e.clientY, ox:MZ.x, oy:MZ.y, id:e.pointerId, live:false }; });
  svg.addEventListener('pointermove', e => {
    if (!drag) return;
    if (!drag.live) {
      if (Math.abs(e.clientX - drag.x) + Math.abs(e.clientY - drag.y) < 5) return;
      drag.live = true; svg.setPointerCapture(drag.id);
    }
    const r = svg.getBoundingClientRect(), s = GEO.W / r.width;
    MZ.x = drag.ox + (e.clientX - drag.x) * s; MZ.y = drag.oy + (e.clientY - drag.y) * s; clampMZ(); applyMZ();
  });
  const stop = () => { drag = null; };
  svg.addEventListener('pointerup', stop); svg.addEventListener('pointercancel', stop); svg.addEventListener('pointerleave', stop);
  svg.addEventListener('wheel', e => {
    e.preventDefault();
    const r = svg.getBoundingClientRect(), s = GEO.W / r.width;
    const mx = (e.clientX - r.left) * s, my = (e.clientY - r.top) * s;
    const f = e.deltaY < 0 ? 1.18 : 1/1.18, k2 = Math.min(8, Math.max(1, MZ.k * f));
    MZ.x = mx - (mx - MZ.x) * (k2 / MZ.k); MZ.y = my - (my - MZ.y) * (k2 / MZ.k); MZ.k = k2; clampMZ(); applyMZ();
    clearTimeout(window.__rp); window.__rp = setTimeout(repin, 160);
  }, { passive: false });
  applyMZ();
}


/* ── bridge surface for the React shell ─────────────────── */
/* one-shot: a React screen names which site section the next visit lands on
   (e.g. its "Network elements" tab), instead of the default Attention */
let __siteSectionPending = null;
window.__nsLegacy = {
  go, drillTo, applyDrillQuery, VIEWS,
  current: () => CURRENT,
  /* the site header, as data — the React Site details / Site equipment
     screens render the same header viewSite draws */
  siteHead: siteHeadData,
  setSection: s => { __siteSectionPending = s; },
  /* map any location tag (sample city codes included) to the real roster row */
  resolveSite: ref => { const r = resolveSite(ref); return r ? { id: r.id, name: r.name } : null; },
  /* resolve which site owns any device */
  siteForNode: (name, ip) => {
    const nr = typeof nodeRecord === 'function' ? nodeRecord(name, ip) : null;
    if (!nr || !nr.loc) return null;
    const s = typeof resolveSite === 'function' ? resolveSite(nr.loc) : null;
    return s ? { id: s.id, name: s.name, cls: nr.cls } : null;
  },
  /* URL-driven only (the LegacyView effect). A null here means the URL has
     no drill — the live DRILL must clear too, or go()'s refresh path keeps
     the stale one and sync() shoves the old drill URL back on top of a
     browser-back navigation, which reads as "back doesn't work". */
  setDrill: d => { DRILL_PENDING = d; if (!d) DRILL = null; },
  /* deep links into detail screens set the id the view reads */
  setParams: (k, p) => {
    if (k === 'site'  && p.id)   {
      SITE_ID = p.id;
      if (p.tab && typeof SITE_TABS !== 'undefined' && SITE_TABS.some(t => t.k === p.tab)) SITE_TAB = p.tab;
      else if (!p.tab) SITE_TAB = 'router';
      SITE_SECTION = __siteSectionPending || 'ne';
      /* React StrictMode fires this effect twice per navigation (mount,
         cleanup, mount again) with no gap between — clearing the pending
         section synchronously here means the second pass reads it as
         already consumed and falls back to the default, silently undoing
         an explicit setSection() from the click that navigated here.
         Deferring the clear lets both passes see the same pending value;
         a setTimeout(0) still lands well before any real next click. */
      setTimeout(() => { __siteSectionPending = null; }, 0);
    }
    if (k === 'capex' && p.id)   { CAPEX_ID = p.id; SITE_ID = p.id; SITE_SECTION = 'capex'; }
    if (k === 'opex'  && p.id)   { OPEX_ID = p.id; SITE_ID = p.id; SITE_SECTION = 'opex'; }
    if (k === 'services' && p.tab) {
      if (['l2vpn', 'l3vpn', 'ibw'].includes(p.tab.toLowerCase())) {
        TAB.svc = p.tab.toLowerCase();
      }
    }
    if (k === 'physical') {
      const targetCls = p.cls || p.tab;
      if (targetCls && PHY_TABS.some(x => x.k === targetCls)) {
        TAB.phy = targetCls;
      } else if (!TAB.phy) {
        const saved = typeof sessionStorage !== 'undefined' ? sessionStorage.getItem('ns_phy_tab') : null;
        TAB.phy = (saved && PHY_TABS.some(x => x.k === saved)) ? saved : 'router';
      }
    }
    if (k === 'resource' && p.name) { RES_ID = p.name; RES_IP = p.ip || null; RES_TAB = 'overview'; RES_ENB_TAB = 'cell'; RES_SW_TAB = 'hardware'; RES_DW_TAB = 'hardware'; }
    if (k === 'node'  && p.name) {
      NODE_ID = p.name;
      NODE_IP = p.ip || null;
      if (p.site) NODE_SITE = p.site;
      else if (typeof LOCATIONS !== 'undefined') {
        const nr = typeof nodeRecord === 'function' ? nodeRecord(NODE_ID, NODE_IP) : null;
        if (nr && nr.loc) {
          const sRec = typeof resolveSite === 'function' ? resolveSite(nr.loc) : null;
          if (sRec) NODE_SITE = sRec.id;
        }
      }
      NODE_TAB = (p.nodetab || (p.tab && ['overview','hardware','links','services','alerts','topology','channels','amplifiers','config','digitaltwins'].includes(p.tab))) ? (p.nodetab || p.tab) : 'overview';
      NODE_PERF = '24h';
      NODE_ALERT_TAB = 'alerts';
      NODE_LINK_PROTO = 'LLDP';
      NODE_HW_SEL = 'bbu';
      NODE_ENB_LINK_TAB = 'backhaul';
    }
    if (k === 'vnfdetails' && p.name) { VNF_DETAIL_ID = p.name; VNF_DETAIL_TAB = 'vdu4g'; }
    if (k === 'cell4gdetails' && p.cell) { CELL_4G_NAME = p.cell; }
    if (k === 'cell5gdetails' && p.cell) { CELL_5G_NAME = p.cell; }
    /* only a move to a *different* frame closes the gallery — this runs on
       every URL sync, including the one go() fires right after a thumbnail
       click, so an unconditional reset would slam the dialog shut again */
    if (k === 'odf' && p.id) {
      const decodedOdf = decodeURIComponent(p.id);
      if (decodedOdf !== ODF_ID) { ODF_ID = decodedOdf; ODF_GALLERY = null; }
    }
    if (k === 'rack' && p.id) {
      const decodedRack = decodeURIComponent(p.id);
      if (decodedRack !== RACK_ID) { RACK_ID = decodedRack; RACK_GALLERY = null; }
    }
    if (k === 'power' && p.id) { POWER_ID = decodeURIComponent(p.id); }
    if (k === 'splice' && p.id) {
      const decodedSplice = decodeURIComponent(p.id);
      if (decodedSplice !== SPLICE_ID) { SPLICE_ID = decodedSplice; SPLICE_GALLERY = null; }
    }
    if (k === 'cord' && p.id) { CORD_ID = decodeURIComponent(p.id); }
    if (k === 'duct' && p.id) { DUCT_ID = decodeURIComponent(p.id); }
    if (k === 'fiber' && p.id) { FIBER_ID = decodeURIComponent(p.id); FIBER_TAB = 'overview'; }
    if (k === 'target' && p.host) {
      const decoded = decodeURIComponent(p.host);
      if (decoded !== TARGET_ID) { TARGET_ID = decoded; TXRUN = 4412; TXSTEP = 0; }
    }
    if (k === 'targets') {
      if (p.job) TGT_JOB_FILTER = decodeURIComponent(p.job).trim();
      else if (!p.drill && !p.job) TGT_JOB_FILTER = null;
    }
  },
  /* React's sidebar collapse drives the same class the prototype's CSS keys on */
  setCollapsed
};
